
/* Passage editor and rehearsal are host controls; no alternate music clock. */
'use strict';
window.HapaPassageUI=function(h){
 const $=id=>document.getElementById(id),P=HapaPassages,C=HapaCore,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let selected=0,loop=null,busy=false;
 $('passages').innerHTML=`<div class="section-label">THE WORLDS ARE PLACES · THE TUNNEL IS A JOURNEY</div><h2>Passages</h2><p class="hint">An opening, a journey, an arrival. Stems shape the material; the score protects the landing time.</p>
 <div class="switchrow"><label><input type="checkbox" id="passageEnabled" checked> Automatic route</label><label><input type="checkbox" id="passagePolish" checked> Solid collars</label></div>
 <div class="micro-status" id="routeCoverage"></div><div class="edit-grid"><button id="routeFlow">Long journeys</button><button id="routeBalanced">Balanced itinerary</button></div><p class="footnote">Replans unlocked route intervals, not shot boundaries. Saved takes and Undo preserve the previous edit.</p><div class="edit-grid"><button id="mixFractal" class="primary">Fractal-first mix</button><button id="mixNew">New-design mix</button></div><p class="footnote">Change treatments without moving an arrival. Original fractal walls, light waves and moving lines remain the primary visual language.</p><div id="routeMap"></div><label class="edit-label">SELECT PASSAGE<select id="passageSelect"></select></label>
 <label class="edit-label">TITLE<input type="text" id="passageLabel" maxlength="80"></label>
 <div class="edit-grid"><label class="edit-label">TREATMENT<select id="passageStyle"><option value="ember-passage">Ember Passage · Fire Paint</option><option value="tidal-conduit">Tidal Conduit · Water Paint</option><option value="circuit-transit">Circuit Transit · Kali traces</option><option value="cloud-slipstream">Cloud Slipstream · protean volume</option><option value="fractal-loom">Golden Loom · original fractal tunnel</option><option value="silken-current">Silken Current · flowing sails</option><option value="oracle-procession">Oracle Procession · 3D guardians</option><option value="crown-engine">Crown Engine · resonant rings</option><option value="reliquary-thread">Reliquary thread · legacy</option><option value="halo-bloom">Halo bloom · legacy</option><option value="iris-bloom">Iris bloom · solid petals</option><option value="braid">Braided crossing</option><option value="threshold">Threshold passage</option><option value="thread">Thread pull</option><option value="media-weave">Media-lined passage</option></select></label><label class="edit-label">DESTINATION PALETTE<select id="passagePalette"></select></label></div>
 <div class="edit-grid"><label class="edit-label">DURATION · SONG SECONDS<input id="passageDuration" type="number" step=".5" min="4" max="60"></label><label class="edit-label">DISTANCE · WORLD UNITS<input id="passageLength" type="number" step="1" min="12" max="54"></label></div>
 <label class="wide-label">DESTINATION APPEARS <output id="revealLabel"></output><input type="range" min=".12" max=".75" step=".01" id="passageReveal"></label>
 <label class="wide-label">CARRY OUTGOING COLOR<input type="range" min="0" max="1" step=".01" id="passageContinuity"></label>
 <div class="switchrow"><label><input id="passageWall" type="checkbox"> Media on walls</label><label><input id="passageLock" type="checkbox"> Protect passage</label></div>
 <button class="full primary" id="applyPassage">Apply passage</button><div class="edit-grid"><button id="rehearsePassage">↻ Rehearse with song</button><button id="stopPassage">Stop rehearsal</button></div>
 <div id="passageEvidence" class="footnote"></div><div class="section-label">PASSAGE INSPECTOR</div><div class="trace" id="passageTrace"></div><p class="footnote">Rehearsal loops this interval, not the entire song. Reduced motion or protected cameras select a quiet, stationary dissolve. World selection switches to a single scene until Automatic route is restored.</p>`;
 C.palettes.forEach(p=>$('passagePalette').add(new Option(p.name,p.id)));
 function open(){document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='passages'));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.id==='passages'));}
 function current(){return h.state().passages.bridges[selected];}
 function refresh(){const s=h.state(),list=s.passages.bridges;selected=Math.min(selected,Math.max(0,list.length-1));$('passageEnabled').checked=s.passages.enabled;$('passagePolish').checked=s.passages.polish;
  const cov=P.coverage(s.passages,h.score().duration);$('routeCoverage').textContent=`${cov.count} journeys · ${(cov.passageRatio*100).toFixed(0)}% in passages · ${(cov.flightRatio*100).toFixed(0)}% forward tunnel flight. Original fractal ${(100*cov.fractalSeconds/Math.max(.001,cov.passageSeconds)).toFixed(0)}% of passage time. Entry/reveal included.`;
  $('passageSelect').innerHTML=list.map((b,i)=>`<option value="${i}">${i+1} · ${esc(b.label)}</option>`).join('');$('passageSelect').value=selected;
  $('routeMap').innerHTML=[s.passages.baseWorld,...list.map(b=>b.to)].map((w,i)=>`<span>${esc(C.worlds.find(x=>x.id===w)?.name||w)}</span>${i<list.length?'<i>→ loom →</i>':''}`).join('');
  const b=current();if(b){$('passageLabel').value=b.label;$('passageStyle').value=b.style;$('passagePalette').value=b.toPalette;$('passageDuration').value=b.duration;$('passageLength').value=b.length;$('passageReveal').value=b.reveal;$('passageContinuity').value=b.continuity;$('passageWall').checked=b.wallMedia;$('passageLock').checked=b.locked;$('revealLabel').textContent=Math.round(b.reveal*100)+'% into flight';$('passageEvidence').textContent=`${b.start.toFixed(2)} → ${b.arrival.toFixed(2)} song seconds · arrival pinned to ${b.toShot}. ${b.cueBasis}`;}
  const track=$('passageTrack');track.innerHTML=list.map((b,i)=>`<button data-bridge="${i}" style="left:${b.start/h.score().duration*100}%;width:${b.duration/h.score().duration*100}%" title="${esc(b.label)} · ${b.start.toFixed(1)} → ${b.arrival.toFixed(1)}"><span>↝</span> ${i+1}</button>`).join('');track.querySelectorAll('button').forEach(x=>x.onclick=()=>{selected=+x.dataset.bridge;refresh();open();h.seek(current().start);});
 }
 for(const [id,pace] of [['routeFlow','flow'],['routeBalanced','balanced']])$(id).onclick=()=>{try{P.replan(h.state(),h.score(),pace);h.refresh();h.mark();}catch(e){h.toast(e.message,true);}};
 for(const [id,mix]of [['mixFractal','fractal-first'],['mixNew','new-designs']])$(id).onclick=()=>{try{P.setMix(h.state(),h.score(),mix);h.refresh();h.mark();h.toast('Tunnel treatments updated; all arrival times retained.');}catch(e){h.toast(e.message,true);}};
 $('passageSelect').onchange=e=>{selected=+e.target.value;refresh();};$('passageReveal').oninput=e=>$('revealLabel').textContent=Math.round(+e.target.value*100)+'% into flight';
 $('passageEnabled').onchange=e=>{h.state().passages.enabled=e.target.checked;HapaEditorial.saveActive(h.state());h.mark();};$('passagePolish').onchange=e=>{h.state().passages.polish=e.target.checked;HapaEditorial.saveActive(h.state());h.mark();};
 $('passageLock').onchange=e=>{try{h.edit(current().id,{locked:e.target.checked});refresh();}catch(err){h.toast(err.message,true);refresh();}};
 $('applyPassage').onclick=()=>{try{h.edit(current().id,{label:$('passageLabel').value,style:$('passageStyle').value,toPalette:$('passagePalette').value,duration:+$('passageDuration').value,length:+$('passageLength').value,reveal:+$('passageReveal').value,continuity:+$('passageContinuity').value,wallMedia:$('passageWall').checked});refresh();h.toast('Passage updated. Arrival and surrounding shot times preserved.');}catch(e){h.toast(e.message,true);}};
 async function rehearse(id){const b=h.state().passages.bridges.find(b=>b.id===id);if(!b)throw Error('Unknown passage');h.state().passages.enabled=true;loop={start:Math.max(0,b.start-1),end:Math.min(h.score().duration,b.arrival+2),id};selected=h.state().passages.bridges.indexOf(b);refresh();open();await h.seek(loop.start);await h.play();return {...loop};}
 function stop(){loop=null;h.pause();h.mark();}
 function loopTick(t){if(loop&&t>=loop.end&&!busy){busy=true;h.seek(loop.start).then(()=>h.play()).finally(()=>busy=false);}}
 function tick(t){const p=P.at(h.state(),t),r=h.renderer().routeTelemetry;const rows=[['Stage',p.stage],['Journey',p.bridge?.label||'—'],['Arrival',p.active?p.arrival.toFixed(3)+' s':'—'],['Remaining',p.active?p.remaining.toFixed(2)+' s':'—'],['Progress',p.active?Math.round(p.progress*100)+'%':'—'],['Camera policy',p.reason||'curated protected corridor'],['Draw policy',r?.primary||'one scene'],['Rehearsal',loop?'looping selected interval':'off']];$('passageTrace').innerHTML=rows.map(([a,b])=>`<div class="tr"><span>${esc(a)}</span><b>${esc(b)}</b></div>`).join('');
  if(p.active){$('sceneTitle').textContent=p.bridge.label;$('sceneIndex').textContent='PASSAGE / '+p.stage.toUpperCase();$('sceneSubject').textContent=`${C.worlds.find(w=>w.id===p.bridge.from)?.name} → Golden Loom → ${C.worlds.find(w=>w.id===p.bridge.to)?.name}`;}
  $('passageTrack').querySelectorAll('button').forEach((x,i)=>x.classList.toggle('current',p.bridge?.id===h.state().passages.bridges[i].id));
 }
 $('rehearsePassage').onclick=()=>rehearse(current().id).catch(e=>h.toast(e.message,true));$('stopPassage').onclick=stop;refresh();return{refresh,tick,loopTick,rehearse,stop};
};

